from itertools import permutations

cargo = ("fuel", "grain", "livestock", "machinery", "produce", "textiles")
solutions = []

for arrangement in permutations(cargo):
    pos = {name: bay for bay, name in enumerate(arrangement, 1)}
    if not (pos["grain"] > pos["livestock"] > pos["textiles"]):
        continue
    if not (pos["produce"] > pos["fuel"]):
        continue
    if abs(pos["textiles"] - pos["produce"]) != 1:
        continue
    if abs(pos["machinery"] - pos["grain"]) != 2:
        continue
    solutions.append(arrangement)

print("Exhaustive enumeration: all 720 cargo arrangements checked.")
print("Valid arrangements:", len(solutions))

if not solutions:
    print("CHECK UNKNOWN: constraints have no satisfying arrangement.")
else:
    determined = {}
    for bay in range(1, 7):
        possible = sorted({arrangement[bay - 1] for arrangement in solutions})
        print("Bay {}: {}".format(bay, ", ".join(possible)))
        if len(possible) == 1:
            determined[bay] = possible[0]

    expected = len(determined)
    options = {"A": 2, "B": 3, "C": 4, "D": 5, "E": 6}
    matching_options = [letter for letter, value in options.items()
                        if value == expected]
    submitted = 3

    print("Completely determined bays:", determined)
    print("Expected count:", expected)
    print("Correct option:", ", ".join(matching_options) or "none")
    print("Submitted count:", submitted)
    print("CHECK PASS" if submitted == expected else "CHECK FAIL")
